import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main2 {
    public static void main(String[] args) {
        InputStream input = System.in;
        OutputStream output = System.out;
        InputHandler in = new InputHandler(input);
        PrintWriter writer = new PrintWriter(output);
        Computator solver = new Computator();
        solver.execute(1, in, writer);
        writer.close();
    }

    static class Computator {
        static final int CAPACITY = 1 << 20;
        static double[] realCos = new double[CAPACITY];
        static double[] realSin = new double[CAPACITY];
        static double[] imagCos = new double[CAPACITY];
        static double[] imagSin = new double[CAPACITY];

        static {
            for (int group = 1; group <= realCos.length; group <<= 1) {
                int half = group >> 1;
                for (int i = half; i < group; i++) {
                    double angle = 2 * Math.PI * (i - half) / group;
                    realCos[i] = Math.cos(angle);
                    realSin[i] = Math.sin(angle);
                    imagCos[i] = Math.cos(-angle);
                    imagSin[i] = Math.sin(-angle);
                }
            }
        }

        void execute(int testId, InputHandler reader, PrintWriter writer) {
            final int MOD = 998244353;
            int n = reader.getInt();
            int k = reader.getInt();
            int[] initial = new int[10];
            for (int i = 0; i < k; i++) {
                int idx = reader.getInt();
                initial[idx] = 1;
            }

            int[] product = {1};
            int exp = n / 2;

            while (true) {
                if ((exp & 1) != 0) {
                    product = combine(product, initial, MOD);
                }
                exp >>= 1;
                if (exp == 0) break;
                initial = combine(initial, initial, MOD);
            }

            long total = 0;
            for (int val : product) {
                total += (long) val * val;
            }
            writer.println(total % MOD);
        }

        int[] combine(int[] first, int[] second, int modulo) {
            int required = first.length + second.length - 1;
            int size = Math.max(2, Integer.highestOneBit(required - 1) << 1);

            double[] re1 = new double[size];
            double[] im1 = new double[size];
            for (int i = 0; i < first.length; i++) {
                int val = ((first[i] % modulo) + modulo) % modulo;
                re1[i] = val & 0x7FFF;
                im1[i] = val >> 15;
            }
            transform(re1, im1, false);

            double[] re2 = new double[size];
            double[] im2 = new double[size];
            for (int i = 0; i < second.length; i++) {
                int val = ((second[i] % modulo) + modulo) % modulo;
                re2[i] = val & 0x7FFF;
                im2[i] = val >> 15;
            }
            transform(re2, im2, false);

            double[] reRes = new double[size];
            double[] imRes = new double[size];

            for (int i = 0; i < size; i++) {
                int j = (size - i) & (size - 1);
                double ar1 = (re1[i] + re1[j]) / 2;
                double ai1 = (im1[i] - im1[j]) / 2;
                double ar2 = (im1[i] + im1[j]) / 2;
                double ai2 = (re1[j] - re1[i]) / 2;

                double br1 = (re2[i] + re2[j]) / 2;
                double bi1 = (im2[i] - im2[j]) / 2;
                double br2 = (im2[i] + im2[j]) / 2;
                double bi2 = (re2[j] - re2[i]) / 2;

                reRes[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
                imRes[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
            }

            transform(reRes, imRes, true);
            int[] result = new int[required];
            for (int i = 0; i < required; i++) {
                long r1 = Math.round(reRes[i]);
                long r2 = Math.round(imRes[i]);
                long r3 = Math.round(imRes[size - i]);
                result[i] = (int) ((r1 + ((r2 % modulo) << 15) + ((r3 % modulo) << 30)) % modulo);
            }
            return result;
        }

        void transform(double[] re, double[] im, boolean inverse) {
            int n = re.length;
            int bits = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << bits) >>> bits;
                if (i < j) {
                    double temp = re[i]; re[i] = re[j]; re[j] = temp;
                    temp = im[i]; im[i] = im[j]; im[j] = temp;
                }
            }

            for (int len = 2; len <= n; len <<= 1) {
                int mid = len >> 1;
                int step = realCos.length / len;

                for (int start = 0; start < n; start += len) {
                    for (int idx = 0, w = 0; idx < mid; idx++, w += step) {
                        double wRe = inverse ? imagCos[mid + idx] : realCos[mid + idx];
                        double wIm = inverse ? imagSin[mid + idx] : realSin[mid + idx];

                        int p = start + idx;
                        int q = start + idx + mid;

                        double uRe = re[p];
                        double uIm = im[p];
                        double vRe = re[q] * wRe - im[q] * wIm;
                        double vIm = re[q] * wIm + im[q] * wRe;

                        re[p] = uRe + vRe;
                        im[p] = uIm + vIm;
                        re[q] = uRe - vRe;
                        im[q] = uIm - vIm;
                    }
                }
            }

            if (inverse) {
                double invN = 1.0 / n;
                for (int i = 0; i < n; i++) {
                    re[i] *= invN;
                    im[i] *= invN;
                }
            }
        }
    }

    static class InputHandler {
        final InputStream source;
        final byte[] buffer = new byte[1024];
        int cursor = 0;
        int limit = 0;

        InputHandler(InputStream source) {
            this.source = source;
        }

        int getInt() {
            int ch = fetch();
            while (isSpace(ch)) ch = fetch();
            int negative = 1;
            if (ch == '-') {
                negative = -1;
                ch = fetch();
            }
            int value = 0;
            do {
                if (ch < '0' || ch > '9') throw new InputMismatchException();
                value = value * 10 + ch - '0';
                ch = fetch();
            } while (!isSpace(ch));
            return value * negative;
        }

        int fetch() {
            if (limit == -1) throw new InputMismatchException();
            if (cursor >= limit) {
                cursor = 0;
                try {
                    limit = source.read(buffer);
                } catch (Exception e) {
                    throw new InputMismatchException();
                }
                if (limit <= 0) return -1;
            }
            return buffer[cursor++] & 0xFF;
        }

        boolean isSpace(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }
    }
}
